			{
				result7 = 1065;
			}
			_ = Thread.CurrentThread.CurrentCulture.LCID;
			parameters.SurveyObj = SelectSurveyWithCompaniesListTree(result, showValues: true, result2, result5, result6, result4, result3);
		}
		StiReport stiReport = new StiReport();
		if (pfCId != 0 && !string.IsNullOrWhiteSpace(_pathReportFiles))
		{
			if (!_pathReportFiles.EndsWith("/"))
			{
				_pathReportFiles += "/";
			}
			_pathReportFiles = _pathReportFiles + pfCId + "/";
		}
