		stiReport.Dictionary.Databases.Add(new StiSqlDatabase("CRMIdealExtra", text));
		if (filePdfPath == "1")
		{
			CreatePdfPath(stiReport, imgResolution, ref filePdfPath);
			if (filePdfPath == "1")
			{
				filePdfPath = "";
			}
		}
		return stiReport;
	}

