	public string ConvertStrDateTimeWithFormat(string dt = "")
	{
		try
		{
			int.TryParse(SysSeting.Get().DefaultLanguageID.ToString(), out var result);
			if (result <= 0)
			{
				result = 1065;
			}
			int lCID = Thread.CurrentThread.CurrentCulture.LCID;
			DateTime dateTime = default(DateTime);
			string text = "";
			try
			{
				if (!string.IsNullOrEmpty(dt))
				{
					text = PersianDate.GetFormatetdDate(dt.Replace("/", ""));
					dt = lCID switch
					{
						1065 => DateTime.Parse(text + " " + DateTime.Now.ToString("HH:mm:ss"), new PersianCulture()).ToString("yyyy/MM/dd"), 
						1025 => DateTime.Parse(text + " " + DateTime.Now.ToString("HH:mm:ss"), new CultureInfo("ar-SA")).ToString("yyyy/MM/dd", new PersianCulture()), 
						_ => DateTime.Parse(text + " " + DateTime.Now.ToString("HH:mm:ss"), new CultureInfo("en-US")).ToString("yyyy/MM/dd", new PersianCulture()), 
					};
				}
				else
				{
					dt = null;
				}
			}
			catch (Exception e)
			{
				ErrorSignal.FromCurrentContext().Raise(e);
				dt = null;
			}
		}
		catch (Exception ex)
		{
			Public.InsExceptToElmah(ex);
			dt = null;
		}
		return dt;
	}

