	public string ConvertPersianToLocalizedDate(string dt = "")
	{
		try
		{
			int.TryParse(SysSeting.Get().DefaultLanguageID.ToString(), out var result);
			if (result <= 0)
			{
				result = 1065;
			}
			int lCID = Thread.CurrentThread.CurrentCulture.LCID;
			DateTime dateTime = default(DateTime);
			try
			{
				if (!string.IsNullOrEmpty(dt))
				{
					dateTime = DateTime.Parse(PersianDate.GetFormatetdDate(dt.Replace("/", "")) + " " + DateTime.Now.ToString("HH:mm:ss"), new PersianCulture());
					switch (lCID)
					{
					case 1065:
						dt = dateTime.ToString("yyyy/MM/dd", new PersianCulture());
						break;
					case 1025:
					{
						CultureInfo cultureInfo = new CultureInfo("ar-SA");
						cultureInfo.DateTimeFormat.Calendar = new UmAlQuraCalendar();
						dt = dateTime.ToString("yyyy/MM/dd", cultureInfo);
						break;
					}
					default:
						dt = dateTime.ToString("yyyy/MM/dd", CultureInfo.InvariantCulture);
						break;
					}
				}
				else
				{
					dt = null;
				}
			}
			catch (Exception e)
			{
				ErrorSignal.FromCurrentContext().Raise(e);
				dt = null;
			}
		}
		catch (Exception ex)
		{
			Public.InsExceptToElmah(ex);
			dt = null;
		}
		return dt;
	}

